package com.drogaria.backend.service;
import com.drogaria.backend.dto.LogAuditoriaRequest; import com.drogaria.backend.entity.LogAuditoria; import com.drogaria.backend.repository.*; import org.springframework.stereotype.Service; import java.time.LocalDateTime;
@Service public class LogAuditoriaService { private final LogAuditoriaRepository r; private final FuncionarioRepository funcionarios; public LogAuditoriaService(LogAuditoriaRepository r,FuncionarioRepository f){this.r=r;funcionarios=f;} public LogAuditoria registrar(LogAuditoriaRequest x){LogAuditoria l=new LogAuditoria();l.setAcao(x.getAcao());l.setDataHora(LocalDateTime.now());if(x.getIdFuncionario()!=null)l.setFuncionario(funcionarios.findById(x.getIdFuncionario()).orElse(null));return r.save(l);} public java.util.List<LogAuditoria> listar(){return r.findAll();} }